    #include <climits>
#include <iostream>
#include <queue>
#include <sstream>
#include <vector>
using namespace std;

class Node
{
  public:
    int data;
    Node *left;
    Node *right;

    Node(int val)
    {
        data = val;
        left = right = nullptr;
    }
};

// DFS to check all descendants of an ancestor
void findDiff(Node *ancestor, Node *curr, int &ans)
{

    if (curr == nullptr)
        return;

    // Update maximum difference
    ans = max(ans, ancestor->data - curr->data);

    findDiff(ancestor, curr->left, ans);
    findDiff(ancestor, curr->right, ans);
}

// Treat every node as ancestor
void traverse(Node *root, int &ans)
{

    if (root == nullptr)
        return;

    findDiff(root, root->left, ans);
    findDiff(root, root->right, ans);

    traverse(root->left, ans);
    traverse(root->right, ans);
}

int maxDiff(Node *root)
{

    int ans = INT_MIN;

    traverse(root, ans);

    return ans;
}

// Function to build tree from level order input
Node *buildTree(string str)
{

    if (str.size() == 0 || str[0] == 'N')
        return nullptr;

    vector<string> ip;
    stringstream ss(str);
    string temp;

    while (ss >> temp)
        ip.push_back(temp);

    Node *root = new Node(stoi(ip[0]));

    queue<Node *> q;
    q.push(root);

    int i = 1;

    while (!q.empty() && i < ip.size())
    {

        Node *curr = q.front();
        q.pop();

        if (ip[i] != "N")
        {
            curr->left = new Node(stoi(ip[i]));
            q.push(curr->left);
        }
        i++;

        if (i >= ip.size())
            break;

        if (ip[i] != "N")
        {
            curr->right = new Node(stoi(ip[i]));
            q.push(curr->right);
        }
        i++;
    }

    return root;
}

int main()
{

    // Construct the following binary tree
    //        5
    //       / \
    //      2   1

    Node *root = new Node(5);
    root->left = new Node(2);
    root->right = new Node(1);

    cout << maxDiff(root);

    return 0;
}


